8	/** A single pending mutation parsed from one line of import text. */
9	export interface PendingItem {
10	  /** "add" or "update" — mirrors the residual CLI verb. */
11	  kind: "add" | "update";
12	  /** The force/entity type, e.g. "stressor", "component", "term". */
13	  type: string;
14	  /**
15	   * All recognized flags for this line, keyed by kebab-case flag name
16	   * (matching the real `--flag-name` CLI syntax) with their string value.
17	   * Flags declared `multiple: true` in the CLI schema are NOT stored here;
18	   * they appear in `multipleFields` instead.
19	   */
20	  fields: Record<string, string>;
21	  /**
22	   * Values for flags declared `multiple: true` in the CLI schema (e.g.
23	   * `--add-component`/`--remove-component` on `update stressor` /
24	   * `update purpose`), keyed by kebab-case flag name, collecting every
25	   * occurrence in the order they appeared on the line.
26	   */
27	  multipleFields: Record<string, string[]>;
28	  /** The original source line, verbatim, for display/debugging. */
29	  raw: string;
30	}
31	
32	/** A line that failed to parse into a PendingItem, with a human-readable reason. */
33	export interface ParseError {
34	  /** The original source line, verbatim. */
35	  line: string;
36	  /** Human-readable description of why the line could not be parsed. */
37	  message: string;
38	}
39	
40	/** Result of parsing a full block of pasted import text. */
41	export interface ParseResult {
42	  items: PendingItem[];
43	  errors: ParseError[];
44	}
45	
46	import cliSchema from "../generated/cli-schema.json";
47	
48	/** Flag metadata as recognized internally by the parser, for one subcommand. */
49	export interface KnownFlag {
50	  name: string;
51	  required: boolean;
52	  multiple: boolean;
53	}
54	
55	interface SchemaFlag {
56	  name: string;
57	  required: boolean;
58	  multiple: boolean;
59	}
60	
61	interface SchemaEntry {
62	  subcommand: string;
63	  flags: SchemaFlag[];
64	}
65	
66	const schema = cliSchema as SchemaEntry[];
67	
68	const knownFlagsBySubcommand = new Map<string, KnownFlag[]>(
69	  schema.map((entry) => [
70	    entry.subcommand,
71	    entry.flags.map((flag) => ({
72	      name: flag.name,
73	      required: flag.required,
74	      multiple: flag.multiple,
75	    })),
76	  ]),
77	);
78	
79	/**
80	 * Returns the parser's internal record of known flags for a given
81	 * "add <type>" / "update <type>" subcommand string (e.g. "update stressor"),
82	 * or undefined if the subcommand is not recognized at all.
83	 *
84	 * This is the table the parity test walks `cli-schema.json` against: for
85	 * every `{ subcommand, flags }` entry there, every flag name must appear
86	 * here with matching `required`/`multiple`.
87	 */
88	export function getKnownFlags(subcommand: string): KnownFlag[] | undefined {
89	  return knownFlagsBySubcommand.get(subcommand);
90	}
91	
92	/**
93	 * Tokenizes a single command line into shell-style words, honoring
94	 * double-quoted segments (`--description "some text"` -> one token
95	 * `some text`) and `\"` escapes within a quoted segment.
96	 *
97	 * Exported for reuse by the parity test and for direct unit testing of
98	 * quoting edge cases.
99	 */
100	export function tokenizeCommandLine(line: string): string[] {
101	  const tokens: string[] = [];
102	  let current = "";
103	  let inQuotes = false;
104	  let hasToken = false;
105	
106	  for (let i = 0; i < line.length; i++) {
107	    const char = line[i];
108	
109	    if (inQuotes) {
110	      if (char === "\\" && line[i + 1] === '"') {
111	        current += '"';
112	        i++;
113	      } else if (char === '"') {
114	        inQuotes = false;
115	      } else {
116	        current += char;
117	      }
118	      continue;
119	    }
120	
121	    if (char === '"') {
122	      inQuotes = true;
123	      hasToken = true;
124	      continue;
125	    }
126	
127	    if (char === " " || char === "\t") {
128	      if (hasToken) {
129	        tokens.push(current);
130	        current = "";
131	        hasToken = false;
132	      }
133	      continue;
134	    }
135	
136	    current += char;
137	    hasToken = true;
138	  }
139	
140	  if (hasToken) {
141	    tokens.push(current);
142	  }
143	
144	  return tokens;
145	}
