  padding: 0.4rem 0.55rem;
  text-align: center;
  background: var(--surface);
  white-space: nowrap;
}
table.matrix thead th {
  position: sticky;
  top: 0;
  z-index: 5;
  color: var(--muted);
  font-weight: 600;
  cursor: pointer;
  user-select: none;
}
table.matrix thead th:hover { color: var(--accent); }
table.matrix tfoot th, table.matrix tfoot td {
  position: sticky;
  bottom: 0;
  z-index: 5;
